import json,pathlib,html
D=pathlib.Path(__file__).resolve().parent;R=D.parents[2];O=R/'outputs'/D.name
p=json.loads((D/'final_plan.json').read_text(encoding='utf8'));route=json.loads((D/'route_plan.json').read_text(encoding='utf8'));src=json.loads((D/'map_sources.json').read_text(encoding='utf8'));s=next(s for s in p['sheets'] if s['kind']=='route');H=html.escape
def card(row,color):
 label={'黄色':'最優先','緑':'次優先','青系':'行けたら'}[color];css={'黄色':'yellow','緑':'green','青系':'blue'}[color]
 return f'''<article class="stop {css}" data-color="{color}"><div class="meta"><span class="priority">{label}</span><span>{H(row[1])}</span></div><h3>{H(row[2])}</h3><div class="booth">{H(row[3])}</div><p class="hall">{H(row[4])}</p><div class="item"><strong>見る展示</strong><p>{H(row[6]).replace(chr(10),'<br>')}</p></div><p>{H(row[7])}</p><a class="map" href="{H(row[8])}" target="_blank" rel="noopener">このエリアの公式小間図を開く ↗</a></article>'''
sections=[]
for area in route['areas']:
 code=area['area'][0];rows=[(r,c) for r,c in zip(s['values'],s['row_colors']) if r[0]==code];core=[card(r,c) for r,c in rows if c=='黄色'];optional=[card(r,c) for r,c in rows if c!='黄色'];label=area['area'][2:]
 sections.append(f'''<section id="area-{code}"><div class="area-heading"><span>{code}</span><h2>{H(label)}</h2></div><p>{H(area['move'])}</p><p class="skip"><strong>時間がなければ</strong><br>{H(area['cut'])}</p>{''.join(core) or '<p>黄色の訪問先はありません。余裕がある場合の追加エリアです。</p>'}<details class="optional"><summary>近くの緑・青を表示（{len(optional)}社）</summary><p>{H(area['optional'])}</p>{''.join(optional)}</details><a class="back" href="#top">先頭へ戻る ↑</a></section>''')
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f2f5f7;color:#203543;font:17px/1.75 -apple-system,BlinkMacSystemFont,"Yu Gothic UI",Meiryo,sans-serif;overflow-wrap:anywhere}header{background:#173f52;color:white;padding:26px 18px}header p{margin:8px 0}h1{font-size:25px;line-height:1.5;margin:8px 0 12px}h2{font-size:22px;line-height:1.5;margin:0}h3{font-size:20px;line-height:1.5;margin:10px 0}main{max-width:760px;margin:auto;padding:14px}nav{position:sticky;top:0;z-index:5;display:flex;gap:6px;padding:8px;background:#fff;border-bottom:1px solid #ccd8df;overflow-x:auto}nav a{flex:1;min-width:55px;white-space:nowrap;text-align:center;text-decoration:none;background:#edf3f6;border-radius:6px;padding:10px 6px;color:#174a63;font-size:15px;font-weight:600}a{color:#075f95}section{scroll-margin-top:78px;margin:16px 0 26px;background:#fff;border:1px solid #d6e0e6;border-radius:10px;padding:16px}.area-heading{display:flex;align-items:center;gap:10px}.area-heading>span{background:#173f52;color:white;min-width:38px;text-align:center;border-radius:5px;padding:4px}.stop{margin:18px 0;padding:15px;border:1px solid #b8cad4;border-left:7px solid #b8cad4;border-radius:7px;background:white}.stop.yellow{border-left-color:#dfbd00;background:#fffde6}.stop.green{border-left-color:#74a254;background:#f4faef}.stop.blue{border-left-color:#699fcb;background:#f2f8fd}.meta{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:14px}.priority{padding:3px 10px;border-radius:4px;font-weight:700;background:#e8eef2}.yellow .priority{background:#ffed57}.green .priority{background:#d9ead3}.blue .priority{background:#cfe2f3}.booth{font-size:28px;font-weight:750;letter-spacing:.03em;line-height:1.4;margin-top:10px}.hall{margin:0 0 12px;color:#506674}.item{border-top:1px solid #d2dde3;padding-top:12px}.item p{margin:5px 0 0}.map,.back{display:block;padding:13px 9px;min-height:48px;text-align:center;border:1px solid #b9ced9;border-radius:6px;text-decoration:none;font-weight:600;background:white}.back{margin-top:18px}.skip{background:#f7f3e8;padding:12px;border-radius:6px;font-size:16px}.optional{border-top:1px solid #d8e2e7;padding-top:12px;margin-top:24px}summary{cursor:pointer;min-height:52px;padding:13px 9px;background:#edf4f7;border-radius:6px;font-weight:700;color:#15506c}.overview ol{padding-left:24px}.overview li{margin-bottom:12px}.note{font-size:15px;color:#526975}.legend span{display:inline-block;padding:3px 10px;margin:0 5px 5px 0;border-radius:4px}.legend .y{background:#ffed57}.legend .g{background:#d9ead3}.legend .b{background:#cfe2f3}footer{max-width:760px;margin:auto;padding:10px 22px 34px;font-size:15px;color:#536b79}details.notes{padding:14px;border:1px solid #d6e0e6;border-radius:7px}details.notes p{padding:0 5px}@media(min-width:800px){header{padding:30px calc((100% - 724px)/2)}nav{justify-content:center}nav a{flex:none;min-width:120px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
doc=f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JIMTOF2026 スマホ巡回ガイド</title><style>{css}</style></head><body id="top"><header><p>JIMTOF2026｜訪問先一覧の更新版</p><h1>黄色11社を先に回る<br>スマホ巡回ガイド</h1><p>訪問予定34社。緑・青は各エリアの<br>「近くの緑・青を表示」から開けます。</p></header><nav aria-label="エリア移動"><a href="#area-A">東1–3</a><a href="#area-B">東7–8</a><a href="#area-C">南1–2</a><a href="#area-D">南3–4</a><a href="#area-E">西</a></nav><main><section class="overview"><h2>基本の回り方</h2><p><strong>東1 → 東2を通過 → 東3 → 東8 → 東7 → 南2 → 南3</strong></p><div class="legend"><span class="y">黄：最優先</span><span class="g">緑：次優先</span><span class="b">青：行けたら</span></div><p>入口・実演時刻は未指定の暫定順です。黄色を先に確保し、緑は3～5社程度から選び、青は残時間で判断してください。</p><p class="skip">東7から南2への移動は、公式図の無料巡回バスを利用候補に。運行・混雑・待ち時間は当日確認。</p><details class="notes"><summary>時間配分・使い方</summary><p>黄色11社に各20～30分、移動・待ち60～90分、休憩45分なら約5時間25分～7時間45分の仮置きです。実演待ちは別。34社すべてを回る前提ではありません。</p><p>2日なら、1日目を東、2日目を南と追加エリアに分けます。南3・4と西3・4は4F。今回、西には黄色がありません。</p><p>HTML本体は画像や外部スクリプトを使わず表示できます。公式小間図のリンク先を開く際は通信が必要です。</p><p>WintechはAI側の緑／自動化側の青を保持し、巡回は青の保留枠にしています。</p></details></section>{''.join(sections)}<section><h2>公式図</h2><p><a class="map" href="https://www.jimtof.org/jp/exhi_search_booth.html">公式小間割図検索 ↗</a></p><p><a class="map" href="https://jimtof.org/files/site_map_jp.pdf">会場全体図・巡回バス ↗</a></p></section></main><footer>作成：2026-10-26。公式小間図を参照した地域ごとの順序案です。通路の実測最短経路、個別展示・実演、当日の移動時間を確認したものではありません。元のExcel・HTMLは保持しています。</footer></body></html>'''
